/*
 * A327317  Triangular array read by rows: row n shows the coefficients of
 *          this polynomial of degree n: p(x,n) = 2^(n-1) ((x+r)^n -
 *          (x+s)^n)/(r - s), where r = 2 and s = 1/2.
 * https://oeis.org/A327317
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabl
 * Formula:   a(n) is the (n‑th) coefficient in the triangular array *
 *            generated by p(x, r) = 2^(r-1) * ((x+2)^r – (x+1/2)^r) / (2 –
 *            1/2). * For the n‑th term we find the row r satisfying *
 *            r(r+1)/2 ≥ n and (r-1)r/2 < n, * then k = n – (r-1)r/2 – 1 (0 ≤
 *            k < r). * The coefficient equals * binom(r, k) * (2^(2r‑k...
 * Range:     u8 n <= 10, u16 n <= 29, u32 n <= 43, u64 n <= 43, u128 n <= 43,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>   /* for uint64_t */

static inline seq_t pow2seq(idx_t exp) {
    seq_t v = 1;
    for (idx_t i = 0; i < exp; ++i)
        v <<= 1;          /* 2^exp in seq_t */
    return v;
}

static inline seq_t binom_seq(idx_t n, idx_t k) {
    if (k > n - k) k = n - k;      /* use symmetry */
    seq_t b = 1;
    for (idx_t i = 1; i <= k; ++i) {
        /* b = b * (n-k+i) / i; exact division each step */
        b = b * (seq_t)(n - k + i) / (seq_t)i;
    }
    return b;
}

seq_t a(idx_t n) {
    if (n < 1) return 0;           /* out of range, but unspecified */

    /* Find r such that r(r+1)/2 >= n */
    idx_t r = 1;
    idx_t tri = 1;                 /* r*(r+1)/2 */
    while (tri < n) {
        ++r;
        tri = r * (r + 1) / 2;
    }

    idx_t prev_tri = (r - 1) * r / 2;
    idx_t k = n - prev_tri - 1;    /* 0 <= k < r */

    seq_t bin = binom_seq((idx_t)r, (idx_t)k);
    seq_t pow1 = pow2seq(2 * r - k);
    seq_t pow2 = pow2seq(k);
    seq_t diff = pow1 - pow2;
    seq_t val = diff / 3;          /* division is exact */
    return bin * val;
}
